 def shot(self,name,selector=None):
  p=self.page;p.evaluate("async()=>{await document.fonts.ready;document.activeElement?.blur();document.querySelectorAll('img').forEach(i=>i.loading='eager');await Promise.all([...document.images].map(i=>i.decode().catch(()=>{})));await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));}")
  p.wait_for_function('()=>!document.querySelector("#toast").textContent');path=str(OUT/(base.base.ENGINE+'-'+name+'.png'))
  p.locator(selector).screenshot(path=path,animations='disabled',style='.skip:not(:focus){visibility:hidden}') if selector else p.screenshot(path=path,full_page=True,animations='disabled',style='.skip:not(:focus){visibility:hidden}')
