  p.goto(base.base.BASE+'/sports/lacrosse/youth');p.locator('.club-result h2 a').first.click();p.wait_for_selector('.my-club-association');org=p.locator('[data-my-club]').get_attribute('data-my-club');self.shot('club-detail');p.get_by_role('button',name='Save as My Club',exact=True).click();self.assertIn('Saved as My Club',p.locator('.my-club-association [role=status]').inner_text());self.shot('my-club-confirmation');p.get_by_role('link',name='View athlete and My Club',exact=False).click();p.wait_for_selector('#show-tryouts');a=self.state()['profiles'][0];self.assertEqual(a['clubId'],org);self.assertIn(org,a['saved']);self.assertNotIn('recruiting',a['modules']);self.assertEqual(a['id'],athlete)
